#!/usr/bin/env node
/*
 * Build probe/fit-probe.js: the real extractor modules + the probe reporter, as one
 * snippet to paste into the DevTools console on any product page.
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const parts = ['extension/lib/sizes.js', 'extension/lib/contract.js', 'extension/lib/score.js', 'extension/lib/classification.js', 'extension/lib/extract.js', 'probe/probe-report.js'];

const header = `/*
 * FitCheck fit probe — GENERATED by scripts/build-probe.js, do not edit by hand.
 * Paste into the DevTools console on a product page. Reports which extraction tiers
 * hit and which contract fields each one fills. Read-only; nothing leaves your machine.
 */
`;
// Wrapped in a block so re-pasting on the same page does not collide with earlier runs.
const body = parts.map((p) => `// ---- ${p}\n${fs.readFileSync(path.join(ROOT, p), 'utf8')}`).join('\n');
const output = `${header}{\n${body}\n}\n`;
const target = path.join(ROOT, 'probe/fit-probe.js');
if (process.argv.includes('--check')) {
  if (!fs.existsSync(target) || fs.readFileSync(target, 'utf8') !== output) {
    console.error('probe/fit-probe.js is stale; run npm run build:probe');
    process.exitCode = 1;
  } else console.log('probe/fit-probe.js is current');
} else {
  fs.writeFileSync(target, output);
  console.log(`wrote probe/fit-probe.js (${parts.length} parts)`);
}
